package io.github.enricoag1982.cairn.codegen;

/** Puts a generated file together: the comment that says where it comes from, the package, the imports and the body. */
final class SourceFile {

    private SourceFile() {
    }

    static String assemble(Model model, Imports imports, Source body) {
        StringBuilder text = new StringBuilder();
        text.append("// Generated by Cairn (cairn-codegen) from ").append(String.join(", ", model.documents()))
                .append(".\n");
        text.append("// Do not edit: the file is overwritten whenever the types are generated again.\n");
        text.append("package ").append(model.packageName()).append(";\n\n");
        if (!imports.declarations().isEmpty()) {
            imports.declarations().forEach(declaration -> text.append(declaration).append('\n'));
            text.append('\n');
        }
        return text.append(body).toString();
    }
}
